/* Signature Croatian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ivanmir": "From Ivan + mir (peace).", "Anaslava": "From Ana + slava (glory).", "Markomil": "From Marko + mil (dear).", "Marijaslava": "From Marija + slava.", "Josipmir": "From Josip + mir.", "Petramor": "From Petra + more (sea).", "Ivanmirić": "Signature surname in -ić style.", "Anaslavić": "Signature surname in -ić style.", "Markomilić": "Signature surname in -ić style.", "Petramorić": "Signature surname in -ić style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ivanmir';
console.log(lookup(q));

